        max: Optional['types.WalletTransactionMaxAggregateInput'] = None,
        having: Optional['types.WalletTransactionScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.WalletTransactionCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.WalletTransactionScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.WalletTransactionScalarFieldKeys', 'types.SortOrder']]]] = None,
